    "Sertifikat kalibrasi untuk instrumen ukur — dan, jika instrumen berada di bawah kontrol metrologi legal, sertifikat verifikasinya",
  "The meter manufacturer, or a contracted calibration company — must show the most recent calibration date":
    "Produsen meter, atau perusahaan kalibrasi kontrak — harus menunjukkan tanggal kalibrasi terbaru",
  "Installation diagram — process flow with measurement points marked":
    "Diagram instalasi — alur proses dengan titik pengukuran yang ditandai",
  "The engineering/plant design team": "Tim desain teknik/pabrik",
  "Internal QA record — the review log before data is submitted":
    "Catatan QA internal — log tinjauan sebelum data dikirim",
  "Verification report for purchased precursor emissions data":
    "Laporan verifikasi untuk data emisi prekursor yang dibeli",
  "Contract or PPA — the electricity purchase agreement":
    "Kontrak atau PPA — perjanjian pembelian listrik",
  "Laboratory analysis reports for calculation factors":
    "Laporan analisis laboratorium untuk faktor perhitungan",
  "Justification for using default values":
    "Pembenaran penggunaan nilai default",
  "Evidence of the carbon price due or paid in the country of origin":
    "Bukti harga karbon yang harus dibayar atau telah dibayar di negara asal",
