  "5 · Payable share": "5 · Bagian yang harus dibayar",
  "Heat number": "Nomor peleburan",
  "An upstream precursor of your own": "Prekursor hulu milik Anda sendiri",
  "Matched to an installation already on file.":
    "Dicocokkan dengan instalasi yang sudah tersimpan.",
  "Recorded — the exporter will confirm this is a new installation.":
    "Dicatat — eksportir akan mengonfirmasi bahwa ini instalasi baru.",
  "{depth} tiers upstream of you": "{depth} tingkat di hulu Anda",
  "Not eligible for actual value — see the data-origin note below":
    "Tidak memenuhi syarat untuk nilai aktual — lihat catatan asal data di bawah",
  "Passed the four-check verification gate":
    "Lolos gerbang verifikasi empat pemeriksaan",
  "Forced to 0 — scrap carries no embedded emissions.":
    "Dipaksa menjadi 0 — skrap tidak membawa emisi tertanam.",
  "From the CBAM catalogue — locked to the CN code beside it.":
    "Dari katalog CBAM — terkunci pada kode CN di sebelahnya.",
  "From the CBAM catalogue — locked to the product beside it.":
    "Dari katalog CBAM — terkunci pada produk di sebelahnya.",
  "From this supplier's own CBAM communication.":
    "Dari komunikasi CBAM pemasok ini sendiri.",
  'It cannot be edited while the origin is "default value".':
    'Tidak dapat diedit selama asalnya "nilai default".',
  "Pick a CN code and the product name fills in.":
    "Pilih kode CN dan nama produk akan terisi.",
