    "Mengandalkan default untuk prekursor langsung cenderung menaikkan angka keseluruhan untuk produk ini, dan dapat berakhir mendekati — bahkan di atas — nilai default untuk barang jadi itu sendiri.",
  "Bound — counted": "Terikat — dihitung",
  "Uploaded — needs binding": "Diunggah — perlu dikaitkan",
