  "Extraction failed.": "Ekstraksi gagal.",
  "File too large to keep in the browser":
    "Berkas terlalu besar untuk disimpan di peramban",
  "Nothing stored to open": "Tidak ada yang tersimpan untuk dibuka",
  "Nothing was written.": "Tidak ada yang ditulis.",
  "The coverage gap stays open.": "Kekurangan cakupan tetap terbuka.",
  "The index entry was saved without the bytes.":
    "Entri indeks disimpan tanpa byte file.",
  "This is why a backend is the next step.":
    "Inilah sebabnya layanan backend menjadi langkah berikutnya.",
