    "Anda mengetik nama, dan tetap tersedia untuk pengecualian lebih lanjut.",
  "Everything already sent about this plant is filed under it, so it cannot be changed from here — if it names the wrong plant, stop and tell the exporter rather than answering for the wrong site.":
    "Semua yang sudah dikirim tentang pabrik ini diarsipkan di bawahnya, sehingga tidak dapat diubah dari sini — jika namanya salah, hentikan dan beri tahu eksportir alih-alih menjawab untuk lokasi yang salah.",
  "Installation saved": "Instalasi disimpan",
