  "Total content of elements other than aluminium":
    "Total kandungan unsur selain aluminium",
  "Only if it exceeds 1 %.": "Hanya jika melebihi 1 %.",
  "Clinker-to-cement ratio": "Rasio klinker terhadap semen",
