  "Nitrogen as ammonium (NH₄⁺)": "Nitrogen sebagai amonium (NH₄⁺)",
  "Nitrogen as nitrate (NO₃⁻)": "Nitrogen sebagai nitrat (NO₃⁻)",
  "Nitrogen as urea": "Nitrogen sebagai urea",
