  "This is what I found. Check each figure against your file and change anything that is not right — nothing goes into the form until you confirm.":
    "Ini yang saya temukan. Periksa setiap angka terhadap berkas Anda dan ubah yang tidak benar — tidak ada yang masuk ke formulir sebelum Anda mengonfirmasi.",
