    "Bagian barang ini dari meteran bersama di bawah.",
  "Process gases such as blast-furnace or coke-oven gas, by their energy content — or by volume and composition, gas by gas.":
    "Gas proses seperti gas tanur tinggi atau gas tanur kokas, berdasarkan kandungan energinya — atau berdasarkan volume dan komposisi, gas per gas.",
  "The balance, from the gases above": "Saldo, dari gas di atas",
