  "My cells are not all one type, or the lines run differently":
    "Sel saya tidak semuanya satu tipe, atau lini berjalan berbeda",
  "What the steel is made of": "Bahan pembentuk baja",
  "Product composition": "Komposisi produk",
  "The alloying elements of what was made this month, from the mill test certificates, weighted by the heats cast.":
    "Unsur paduan dari yang dibuat bulan ini, dari sertifikat uji pabrik, dibobot berdasarkan peleburan yang dicor.",
  "The report states Mn, Cr, Ni and the other alloying elements for the year: the months' figures, weighted by what was made in each. Leave a month empty if it was ordinary carbon steel with only trace elements.":
    "Laporan mencantumkan Mn, Cr, Ni, dan unsur paduan lainnya untuk tahun ini: angka bulanan, dibobot berdasarkan yang dibuat tiap bulan. Kosongkan bulan jika itu baja karbon biasa dengan hanya unsur jejak.",
  "Optional. Weighted by tonnes made across the year in the report.":
    "Opsional. Dibobot berdasarkan ton yang dibuat selama setahun dalam laporan.",
  "Manganese.": "Mangan.",
  "Chromium.": "Kromium.",
  "Nickel.": "Nikel.",
  "All other alloying elements together.":
    "Semua unsur paduan lainnya digabung.",
  "Where the figures come from": "Asal angka-angka ini",
  "So a verifier knows which certificates to ask for.":
    "Agar verifikator tahu sertifikat mana yang harus diminta.",
  "The alloying elements add up to more than 100 %.":
    "Unsur paduan jumlahnya lebih dari 100 %.",
  "Ask about CBAM or Certrace": "Tanya tentang CBAM atau Certrace",
  "Text or CSV · one at a time · or press to choose":
    "Teks atau CSV · satu per satu · atau tekan untuk memilih",
  "What goes to the verifier": "Yang dikirim ke verifikator",
  "Everything this installation hands over for {year}, in one package: the reports you write, and the papers that travel with them.":
    "Semua yang diserahkan instalasi ini untuk {year}, dalam satu paket: laporan yang Anda tulis, dan dokumen yang menyertainya.",
  Attachments: "Lampiran",
  "Not reports you write. Each is an index of papers that travel in the package, beside the reports — and neither holds the package back.":
    "Bukan laporan yang Anda tulis. Masing-masing adalah indeks dokumen yang ikut dalam paket, di samping laporan — dan keduanya tidak menahan paket.",
  "Monitoring plan, operator's emissions report, summary report":
    "Rencana pemantauan, laporan emisi operator, laporan ringkasan",
  Addendum: "Lampiran tambahan",
  "Electricity goes to the EU — one per declarant":
    "Listrik dikirim ke UE — satu per deklaran",
  "Not needed — no electricity goes to the EU":
    "Tidak diperlukan — tidak ada listrik yang dikirim ke UE",
  "Precursor verification reports, supporting evidence":
    "Laporan verifikasi prekursor, bukti pendukung",
  Contains: "Berisi",
  "to get": "untuk didapat",
  "Still to get": "Masih perlu didapat",
  "Each installation you report on hands over one package a year: the monitoring plan, the operator's emissions report and the summary report — a declarant addendum where electricity goes to the EU — and, beside them, the verification reports of your precursors' installations and the supporting evidence. It covers every product the site makes, and downloads once all of it is complete.":
    "Setiap instalasi yang Anda laporkan menyerahkan satu paket setahun: rencana pemantauan, laporan emisi operator, dan laporan ringkasan — lampiran deklaran jika listrik dikirim ke UE — dan, di sampingnya, laporan verifikasi instalasi prekursor Anda serta bukti pendukung. Paket ini mencakup setiap produk yang dibuat lokasi, dan dapat diunduh setelah semuanya lengkap.",
  documents: "dokumen",
  "The product report is not complete": "Laporan produk belum lengkap",
  "{n} of {total} product reports are not complete":
    "{n} dari {total} laporan produk belum lengkap",
  "{n} item(s) of the installation's information are still missing":
    "{n} item informasi instalasi masih belum lengkap",
  "{n} item(s) to do": "{n} item perlu dikerjakan",
  "Monitoring plan": "Rencana pemantauan",
  "Operator's emissions report": "Laporan emisi operator",
  "Operator's summary emissions report": "Laporan ringkasan emisi operator",
  "Declarant-specific addendum": "Lampiran khusus deklaran",
  "Verification reports of precursor installations":
    "Laporan verifikasi instalasi prekursor",
  "Supporting evidence and records": "Bukti pendukung dan catatan",
  "What the installation monitors and how, element by element as the template lists them. The verifier reads it before the year is verified.":
    "Apa yang dipantau instalasi dan bagaimana, elemen demi elemen sebagaimana tercantum di templat. Verifikator membacanya sebelum tahun diverifikasi.",
  "The full report the verifier verifies. It is in English (Article 10(4)).":
    "Laporan lengkap yang diverifikasi verifikator. Dalam bahasa Inggris (Pasal 10(4)).",
  "The shortened report passed on to authorised CBAM declarants (Article 8).":
    "Laporan ringkas yang diteruskan kepada deklaran CBAM yang berwenang (Pasal 8).",
  "One per authorised declarant, only for electricity imported into the EU.":
    "Satu per deklaran berwenang, hanya untuk listrik yang diimpor ke UE.",
  "This installation does not export electricity to the EU, so no addendum is needed.":
    "Instalasi ini tidak mengekspor listrik ke UE, sehingga lampiran tidak diperlukan.",
  "The verification reports of the installations that made your precursors on actual values. The reports themselves are in the package, beside this index.":
    "Laporan verifikasi instalasi yang membuat prekursor Anda dengan nilai aktual. Laporannya sendiri ada dalam paket, di samping indeks ini.",
  "Every document behind a figure, and the figure it supports, so the verifier can sample a month and find its paper. The documents themselves are in the package, beside this index.":
    "Setiap dokumen di balik suatu angka, dan angka yang didukungnya, agar verifikator dapat mengambil sampel satu bulan dan menemukan dokumennya. Dokumennya sendiri ada dalam paket, di samping indeks ini.",
