  "Bills, invoices, meter logs, ERP exports, certificates — as many as you like. Certrace works out what each one is, which month it covers and where it belongs. Nothing is filed until you confirm.":
    "Tagihan, faktur, log meteran, ekspor ERP, sertifikat — sebanyak yang Anda mau. Certrace mengenali setiap dokumen, bulan yang dicakupnya, dan tempat yang sesuai. Tidak ada yang diarsipkan sebelum Anda mengonfirmasi.",
