  "One report per product.": "Satu laporan per produk.",
  "Every product you track gets a report — your own, and any supplier's you have started tracking. Each is built from that product's months, so it always says what its workspace says today.":
    "Setiap produk yang Anda lacak mendapat laporan — milik Anda sendiri, dan milik pemasok yang sudah Anda lacak. Setiap laporan disusun dari bulan produk tersebut, sehingga selalu sesuai dengan kondisi ruang kerjanya saat ini.",
