  "Compliance regulation": "Regulasi kepatuhan",
  "Which regime are you reporting for? Certrace launched on CBAM — the obligation that bites first for exporters into the EU. The rest run on the same engine and switch on as their data models are verified.":
    "Rezim mana yang Anda laporkan? Certrace diluncurkan dengan CBAM — kewajiban yang pertama berlaku bagi eksportir ke UE. Yang lain berjalan di mesin yang sama dan diaktifkan setelah model datanya diverifikasi.",
  "Export route": "Rute ekspor",
