    "EU CBAM Registry · melalui importir / deklaran",
  "What is this declaration for?": "Untuk apa deklarasi ini?",
  "Choose one — the official CBAM filing, or a specific buyer's data request. Each has its own qualification checklist, so keep the two separate.":
    "Pilih salah satu — pelaporan CBAM resmi, atau permintaan data pembeli tertentu. Masing-masing memiliki daftar periksa kualifikasi sendiri, jadi pisahkan keduanya.",
  "CBAM Compliance": "Kepatuhan CBAM",
  "Automatically prepares supplier data collection based on CBAM requirements. Fields, CN codes and templates are generated for you.":
    "Secara otomatis menyiapkan pengumpulan data pemasok berdasarkan persyaratan CBAM. Kolom, kode CN, dan templat dibuatkan untuk Anda.",
  "Buyer Request": "Permintaan Pembeli",
  "Create a custom supplier request for buyer-specific information — documents, certificates and questionnaires on top of the carbon data.":
    "Buat permintaan pemasok khusus untuk informasi spesifik pembeli — dokumen, sertifikat, dan kuesioner di atas data karbon.",
