    "contoh: Permintaan Data Karbon Pembeli ABC",
  "Request name": "Nama permintaan",
  "Shown to suppliers and on every reminder. Make it recognisable.":
    "Ditampilkan kepada pemasok dan di setiap pengingat. Buat agar mudah dikenali.",
  "Request description (optional)": "Deskripsi permintaan (opsional)",
  "Context for your suppliers — what this is for.":
    "Konteks untuk pemasok Anda — untuk apa ini.",
  "e.g. Annual CBAM carbon data for our EU steel exports. Please report at installation level.":
    "contoh: Data karbon CBAM tahunan untuk ekspor baja kami ke UE. Mohon laporkan di tingkat instalasi.",
  "EU buyer / importer (required)": "Pembeli / importir UE (wajib)",
  "EU buyer / importer": "Pembeli / importir UE",
  "Who imports these goods into the EU? Their Authorised CBAM Declarant files the declaration — Certrace addresses the Communication Template and the O3CI share to them.":
    "Siapa yang mengimpor barang ini ke UE? Deklaran CBAM Resmi mereka yang mengarsipkan deklarasi — Certrace mengirimkan Templat Komunikasi dan pembagian O3CI kepada mereka.",
  "The buyer this data request is for.":
    "Pembeli yang dituju permintaan data ini.",
