  "Classification & report fields": "Klasifikasi & kolom laporan",
  "Certrace classified each product automatically — category, CN / HS codes and the CBAM template come from the catalogue and can't be edited. The checklist below reflects the data points that actually apply to the goods you selected.":
    "Certrace mengklasifikasikan setiap produk secara otomatis — kategori, kode CN / HS, dan templat CBAM berasal dari katalog dan tidak dapat diedit. Daftar periksa di bawah mencerminkan titik data yang benar-benar berlaku untuk barang yang Anda pilih.",
  "CBAM report fields": "Kolom laporan CBAM",
  "Carbon data to request": "Data karbon yang diminta",
  "{included} of {total} included": "{included} dari {total} disertakan",
  "These are the data points CBAM requires for the goods you selected. Required fields are locked on; the rest are recommended and on by default — keep or drop them to match how you collect data.":
    "Ini adalah titik data yang diwajibkan CBAM untuk barang yang Anda pilih. Kolom wajib dikunci aktif; sisanya direkomendasikan dan aktif secara default — simpan atau hapus sesuai cara Anda mengumpulkan data.",
  "Choose the carbon-data fields this buyer needs. Recommended fields are pre-selected because buyers commonly ask for them — adjust freely, keeping at least one.":
    "Pilih kolom data karbon yang dibutuhkan pembeli ini. Kolom yang direkomendasikan sudah dipilih karena pembeli umumnya memintanya — sesuaikan sesuka hati, dengan minimal satu kolom tetap dipilih.",
