  "Suppliers, lots & quantities": "Pemasok, lot & jumlah",
  "Map suppliers to each product, then add the production lots you bought in this period. Each lot keeps its own quantity and optional production period, so the embedded-emissions calculation stays fully traceable.":
    "Petakan pemasok ke setiap produk, lalu tambahkan lot produksi yang Anda beli pada periode ini. Setiap lot menyimpan jumlahnya sendiri dan periode produksi opsional, sehingga perhitungan emisi tertanam tetap dapat ditelusuri sepenuhnya.",
  "We produce this ourselves": "Kami memproduksinya sendiri",
  "No Smart Link is sent for {org} — you'll fill this product's data in the portal under your own org profile. Everything after that is identical: AI check, calculation, audit trail.":
    "Tidak ada Smart Link yang dikirim untuk {org} — Anda akan mengisi data produk ini di portal melalui profil organisasi Anda sendiri. Setelah itu semuanya sama: pemeriksaan AI, perhitungan, jejak audit.",
