  "Set the submission deadline suppliers see, and let Certrace chase them automatically so you don't have to.":
    "Atur tenggat pengiriman yang dilihat pemasok, dan biarkan Certrace menindaklanjutinya secara otomatis.",
  "Submission deadline": "Tenggat pengiriman",
