    "Muncul di bagian atas formulir panduan setiap pemasok.",
  "e.g. Please use installation-level actual data where possible. Contact us if you need help.":
    "contoh: Mohon gunakan data aktual tingkat instalasi jika memungkinkan. Hubungi kami jika Anda memerlukan bantuan.",
  "Review & create": "Tinjau & buat",
