  "Where the carbon is.": "Letak karbon.",
  "Every declaration in one place: what the certificates cost, which suppliers and goods carry the emissions, and whose data has aged past the point you should still be filing it.":
    "Setiap deklarasi dalam satu tempat: berapa biaya sertifikat, pemasok dan barang mana yang membawa emisi, dan data siapa yang sudah terlalu lama sehingga tidak layak lagi diarsipkan.",
  "Open cycles": "Siklus terbuka",
  "All time": "Sepanjang waktu",
  "Reading supplier records…": "Membaca catatan pemasok…",
  "No approved emissions data yet.": "Belum ada data emisi yang disetujui.",
  "Once suppliers submit and you approve their figures, the cost, the hotspots and the benchmark all appear here — across every declaration at once.":
    "Setelah pemasok mengirim dan Anda menyetujui angka mereka, biaya, titik panas, dan benchmark akan muncul di sini — di seluruh deklarasi sekaligus.",
  "Go to declarations": "Buka deklarasi",
  "Certificate cost": "Biaya sertifikat",
  "Chargeable tCO₂e": "tCO₂e yang dapat ditagih",
  "{tonnes} t reported": "{tonnes} t dilaporkan",
  "Suppliers costed": "Pemasok yang dihitung biayanya",
  "Saved vs defaults": "Hemat dibanding default",
  "Above defaults": "Di atas default",
  "real data vs fallback": "data nyata dibanding cadangan",
  "Priced at": "Dihargai",
  "{amount} on every tonne you ship. An estimate for planning: the declarant buys at the published auction average for the week of import.":
    "{amount} untuk setiap ton yang Anda kirim. Perkiraan untuk perencanaan: deklaran membeli dengan rata-rata lelang yang dipublikasikan untuk minggu impor.",
  "Certificate price in EUR per tonne CO2e":
    "Harga sertifikat dalam EUR per ton CO2e",
  "Carbon hotspots": "Titik panas karbon",
  "Ranked by absolute chargeable emissions across every declaration in scope — the same mill appearing on four filings counts once, as one relationship.":
    "Diurutkan berdasarkan emisi yang dapat ditagih secara absolut di seluruh deklarasi dalam ruang lingkup — pabrik yang sama yang muncul di empat pengarsipan dihitung sekali, sebagai satu hubungan.",
  "by supplier": "per pemasok",
  "by product": "per produk",
  "{count} of {total} suppliers": "{count} dari {total} pemasok",
  "carry {pct}% of your chargeable emissions — about {amount} in certificates. That's the shortlist for a conversation about actual data, a cleaner route, or a different supplier.":
    "menanggung {pct}% dari emisi Anda yang dapat ditagih — sekitar {amount} dalam sertifikat. Ini adalah daftar pendek untuk percakapan tentang data aktual, rute yang lebih bersih, atau pemasok lain.",
  "Data that needs refreshing": "Data yang perlu diperbarui",
  "Supplier records age. A figure past a year, or one reported for a period you're no longer filing, has to be re-confirmed before it goes into another declaration.":
    "Catatan pemasok menua. Angka yang sudah lebih dari setahun, atau yang dilaporkan untuk periode yang tidak lagi Anda arsipkan, harus dikonfirmasi ulang sebelum dimasukkan ke deklarasi lain.",
  "No supplier records yet — they build up as suppliers submit, and each one makes the next request shorter.":
    "Belum ada catatan pemasok — catatan ini terbentuk seiring pemasok mengirim, dan setiap catatan membuat permintaan berikutnya lebih singkat.",
  "Your one supplier record is current.":
    "Catatan pemasok Anda yang satu ini masih terkini.",
  "All {count} supplier records are current.":
    "Semua {count} catatan pemasok masih terkini.",
