  "fed {count} declarations": "digunakan dalam {count} deklarasi",
  "last updated {days}d ago": "terakhir diperbarui {days} hari lalu",
  "What this is built from": "Dibangun dari apa ini",
  "{datasets} submitted supplier datasets across {declarations} declarations, costed with the same engine the declaration workspace uses — the Annex II direct-only rule for steel and aluminium, default-value markups where a supplier reported on defaults, and any carbon price already paid deducted. Nothing here is a filed figure.":
    "{datasets} dataset pemasok yang dikirim di {declarations} deklarasi, dihitung dengan mesin yang sama dengan ruang kerja deklarasi — aturan hanya-langsung Lampiran II untuk baja dan aluminium, markup nilai default jika pemasok melaporkan dengan default, dan harga karbon yang sudah dibayar dikurangkan. Tidak ada angka di sini yang sudah diarsipkan.",
