    "Hampir selesai — ini membantu kami mendukung Anda sesuai skala yang tepat.",
  "Approximately how many suppliers will you manage in Certrace?":
    "Kira-kira berapa pemasok yang akan Anda kelola di Certrace?",
  "More than 500": "Lebih dari 500",
  "How did you first hear about Certrace?":
    "Bagaimana Anda pertama kali mengetahui Certrace?",
