  "not started (critical)": "belum dimulai (kritis)",
  "No Smart Link goes out for these — {supplier} is you. Report the embedded emissions of your own installation the same way an external supplier would, and the declaration treats it identically: same {regulation} checklist, same AI check, same verification trail.":
    "Tidak ada Smart Link yang dikirim untuk ini — {supplier} adalah Anda. Laporkan emisi terkandung instalasi Anda sendiri dengan cara yang sama seperti pemasok eksternal, dan deklarasi memperlakukannya sama: daftar periksa {regulation} yang sama, pemeriksaan AI yang sama, jejak verifikasi yang sama.",
  "You’re {supplier}. To keep shipping {origin} {sector} into the {destination}, {exporter} has to report the embedded emissions of the goods they buy from you — under {regulation}. This takes about 10 minutes, it’s free, and you don’t need an account.":
    "Anda adalah {supplier}. Untuk terus mengirim {origin} {sector} ke {destination}, {exporter} wajib melaporkan emisi terkandung dari barang yang mereka beli dari Anda — berdasarkan {regulation}. Ini memakan waktu sekitar 10 menit, gratis, dan Anda tidak perlu akun.",
  "Your figures are checked automatically before you submit and land in your own supplier record, so the next declaration starts pre-filled instead of blank. Colleagues can be assigned the sections that belong to their department.":
    "Angka Anda diperiksa otomatis sebelum Anda mengirim dan tersimpan di catatan pemasok Anda sendiri, sehingga deklarasi berikutnya akan terisi awal, bukan kosong. Rekan dapat ditugaskan untuk bagian yang menjadi tanggung jawab departemen mereka.",
  "Your figures are checked automatically before you submit, encrypted, and shared only with {exporter} for this declaration. You can invite colleagues to fill the parts that belong to their department.":
    "Angka Anda diperiksa otomatis sebelum Anda mengirim, dienkripsi, dan hanya dibagikan kepada {exporter} untuk deklarasi ini. Anda dapat mengundang rekan untuk mengisi bagian yang menjadi tanggung jawab departemen mereka.",
