  "Needs a certificate price and a year from 2026":
    "Membutuhkan harga sertifikat dan tahun mulai 2026",
  "Supply chain health": "Kesehatan rantai pasokan",
  "{n} in your chain, {m} on track": "{n} dalam rantai Anda, {m} sesuai jalur",
  "{n} at risk": "{n} berisiko",
  "None at risk": "Tidak ada yang berisiko",
  "Emissions against the EU default": "Emisi dibandingkan default UE",
  "What your goods carry each month, and what the EU would assume for the same tonnes":
    "Emisi yang dibawa produk Anda setiap bulan, dan yang akan diasumsikan UE untuk ton yang sama",
  "Open Carbon & Cost": "Buka Karbon & Biaya",
  charged: "dikenakan",
  "Your data": "Data Anda",
  "Embedded emissions by month against the EU default":
    "Emisi terkandung per bulan dibandingkan default UE",
  "No submitted months to draw yet": "Belum ada bulan terkirim untuk digambar",
  "{n} item(s) are overdue.": "{n} item terlambat.",
  "Your own data saves {amount} against the EU default.":
    "Data Anda sendiri menghemat {amount} dibandingkan default UE.",
  "Nothing is late and nothing worries me. A good time to look ahead.":
    "Tidak ada yang terlambat dan tidak ada yang saya khawatirkan. Waktu yang baik untuk melihat ke depan.",
  "Who is late and what should I chase first?":
    "Siapa yang terlambat dan apa yang harus saya tagih lebih dulu?",
  "What should I do next?": "Apa yang harus saya lakukan selanjutnya?",
  "Which suppliers should I get verified figures from?":
    "Dari pemasok mana saya sebaiknya mendapatkan angka terverifikasi?",
  "What stands out today": "Yang menonjol hari ini",
  "Ask about your data…": "Tanya tentang data Anda…",
