  "Your free trial has ended": "Uji coba gratis Anda telah berakhir",
  "Everything you built is still here and still readable, but nothing can be changed, sent or downloaded until you choose a plan.":
    "Semua yang Anda buat masih ada dan dapat dibaca, tetapi tidak ada yang dapat diubah, dikirim, atau diunduh sampai Anda memilih paket.",
